// Five events. Two are exact duplicates of earlier ones — upstream systems
// retry, and webhooks get replayed. One is aimed at a URL that will fail, to
// exercise the dead-letter path.
//
// In production this node does not exist: the Webhook node feeds Normalise
// directly.

return [
  { json: { event_id: 'evt_1001', type: 'deal.stage_changed', deal: 'Brightpath Dental', from: 'Qualified', to: 'Proposal Sent', value_gbp: 2400, owner: 'ben' } },
  { json: { event_id: 'evt_1002', type: 'deal.stage_changed', deal: 'Vantage Logistics', from: 'Proposal Sent', to: 'Won',           value_gbp: 1800, owner: 'ben' } },
  { json: { event_id: 'evt_1001', type: 'deal.stage_changed', deal: 'Brightpath Dental', from: 'Qualified', to: 'Proposal Sent', value_gbp: 2400, owner: 'ben' } },
  { json: { event_id: 'evt_1003', type: 'deal.stage_changed', deal: 'Meridian Cloud',    from: 'New',       to: 'Qualified',     value_gbp: 950,  owner: 'ben', force_failure: true } },
  { json: { event_id: 'evt_1002', type: 'deal.stage_changed', deal: 'Vantage Logistics', from: 'Proposal Sent', to: 'Won',       value_gbp: 1800, owner: 'ben' } }
];

// Normalise to one shape, then fingerprint it.
//
// The fingerprint is deliberately NOT the upstream event_id alone. Some systems
// reuse ids, some omit them, and some resend the same change under a new id.
// Hashing the meaningful content catches all three. A pure-JS hash is used
// rather than require('crypto') so the node runs identically in any n8n
// deployment, including hosted ones where module access is restricted.

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

return $input.all().map(item => {
  const e = item.json.body ?? item.json;   // webhook payloads arrive under .body

  const normalised = {
    event_id:  e.event_id ?? null,
    type:      e.type ?? 'unknown',
    subject:   e.deal ?? e.record ?? e.name ?? 'unknown',
    from:      e.from ?? null,
    to:        e.to ?? null,
    value_gbp: Number(e.value_gbp ?? 0),
    owner:     e.owner ?? null,
    force_failure: Boolean(e.force_failure)
  };

  // Only content-bearing fields go into the fingerprint, in a fixed order.
  const canonical = [
    normalised.type, normalised.subject, normalised.from,
    normalised.to, normalised.value_gbp
  ].join('|');

  return { json: { ...normalised, fingerprint: fnv1a(canonical), canonical } };
});

// Idempotency gate.
//
// Fire the same event three times and exactly one message goes out. This is the
// single most-requested property in the job posts and almost nobody demonstrates
// it.
//
// State lives in n8n's workflow static data, which survives between executions.
// It is capped and time-bounded so it cannot grow without limit — an unbounded
// seen-set is a memory leak that only shows up in month four.

const TTL_MS = 7 * 24 * 60 * 60 * 1000;   // remember an event for 7 days
const MAX_ENTRIES = 5000;

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const now = Date.now();

// Evict anything past its TTL before deciding anything.
for (const [k, ts] of Object.entries(store.seen)) {
  if (now - ts > TTL_MS) delete store.seen[k];
}

const out = [];
for (const item of $input.all()) {
  const fp = item.json.fingerprint;
  const seenAt = store.seen[fp];

  if (seenAt) {
    out.push({ json: { ...item.json, is_duplicate: true, first_seen_at: new Date(seenAt).toISOString() } });
  } else {
    store.seen[fp] = now;
    out.push({ json: { ...item.json, is_duplicate: false, first_seen_at: new Date(now).toISOString() } });
  }
}

// Hard cap: drop the oldest if the set has grown past the limit.
const keys = Object.keys(store.seen);
if (keys.length > MAX_ENTRIES) {
  keys.sort((a, b) => store.seen[a] - store.seen[b])
      .slice(0, keys.length - MAX_ENTRIES)
      .forEach(k => delete store.seen[k]);
}

return out;

// Audit trail. Every delivered event is recorded with enough detail to answer
// "did this actually go out, and when?" six weeks later without guesswork.

const MAX_LOG = 500;
const store = $getWorkflowStaticData('global');
store.audit = store.audit || [];
store.lastSuccessAt = Date.now();

// itemMatching(i) resolves the paired input item. $('Node').item does NOT
// work inside a .map() — it returns the same item every iteration, which
// silently mislabels every row in the audit trail.
const rows = $input.all().map((item, i) => {
  const src = $('Idempotency Gate').itemMatching(i).json;
  return {
    at: new Date().toISOString(),
    fingerprint: src.fingerprint,
    subject: src.subject,
    outcome: 'delivered',
    status: item.json.statusCode ?? 200
  };
});

store.audit.push(...rows);
if (store.audit.length > MAX_LOG) store.audit = store.audit.slice(-MAX_LOG);

return rows.map(json => ({ json }));

// Dead-letter queue.
//
// A failed delivery is captured with its full payload and the error, so it can
// be replayed after the downstream system is fixed. Without this the event is
// simply gone and nobody finds out until a customer asks.

const MAX_DLQ = 200;
const store = $getWorkflowStaticData('global');
store.dlq = store.dlq || [];

const rows = $input.all().map((item, i) => {
  // itemMatching(i), not .item — see the note in Log Delivered.
  const src = $('Idempotency Gate').itemMatching(i).json;
  return {
    at: new Date().toISOString(),
    fingerprint: src.fingerprint,
    subject: src.subject,
    outcome: 'failed',
    error: item.json.error?.message ?? item.json.message ?? 'delivery failed',
    payload: src,          // everything needed to replay it
    replayable: true
  };
});

store.dlq.push(...rows);
if (store.dlq.length > MAX_DLQ) store.dlq = store.dlq.slice(-MAX_DLQ);

// IMPORTANT: a failed delivery must not stay marked as seen, or a replay would
// be suppressed as a duplicate. Release the fingerprint.
store.seen = store.seen || {};
for (const r of rows) delete store.seen[r.fingerprint];

return rows.map(json => ({ json }));

// Canary.
//
// The failure mode that actually costs clients money is not a loud error — it
// is silence. A webhook quietly stops firing, and nobody notices for a fortnight.
// This runs daily and reports if nothing has been delivered recently.

const QUIET_HOURS = 26;    // a day plus slack, so a late run does not false-alarm

const store = $getWorkflowStaticData('global');
const last = store.lastSuccessAt ?? null;
const hoursSince = last === null ? null : (Date.now() - last) / 3600000;

const silent = last === null || hoursSince > QUIET_HOURS;

return [{
  json: {
    checked_at: new Date().toISOString(),
    last_delivery_at: last === null ? null : new Date(last).toISOString(),
    hours_since_last_delivery: hoursSince === null ? null : Math.round(hoursSince * 10) / 10,
    dlq_depth: (store.dlq || []).length,
    silent,
    verdict: silent
      ? 'NO DELIVERIES IN ' + QUIET_HOURS + 'H — the pipeline may be broken upstream'
      : 'healthy'
  }
}];
